package com.example.rpg.service;
import com.example.rpg.domain.*; import com.example.rpg.repository.CharacterRepository; import org.springframework.stereotype.Service; import java.util.*;
/** Application service coordinates domain behavior while depending only on repository interfaces. */
@Service public final class AdventureService { private final CharacterRepository saves; private final MonsterFactory monsters; public AdventureService(CharacterRepository saves,MonsterFactory monsters){this.saves=saves;this.monsters=monsters;} public PlayerCharacter loadOrCreate(long userId,String name){return saves.findByUserId(userId).map(SaveSnapshot::toCharacter).orElseGet(()->new PlayerCharacter(userId,name));} public void save(PlayerCharacter p){
        // Convert the mutable aggregate to an immutable snapshot before crossing the persistence boundary.
        saves.save(SaveSnapshot.from(p));} public AdventureAction explore(PlayerCharacter p){List<String> places=List.of("Moonlit Marsh","Whispering Woods","Crystal Cavern","Sunken Ruins"); // Allow-list prevents arbitrary locations from entering state.
        String place=places.get(new Random().nextInt(places.size()));p.moveTo(place);Item treasure=new Item("treasure-"+place.replace(' ','-'),"Ancient Treasure",ItemType.TREASURE,Rarity.RARE,0,25);p.collect(treasure);p.reward(20,treasure.value());return new ExploreAction(place);} public BattleAction battle(PlayerCharacter p){Monster m=monsters.randomMonster(p.level());int damage=Math.max(0,m.attackPower()-(p.armor()==null?0:p.armor().power()));boolean won=p.attackPower()>=m.health();p.takeDamage(won?damage:Math.max(damage, p.maxHealth()/2));if(won)p.reward(m.rewardXp(),m.rewardGold());else if(!p.isAlive())p.heal();return new BattleAction(m.name(),won,damage);} }
